package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import org.mockito.exceptions.base.MockitoException;
import org.mockito.internal.util.Checks;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

public class GenericMetadataSupport_actualTypeArguments_TriageGen1Test {

    private GenericMetadataSupport genericMetadataSupport;
    private Class<?> mockRawType;

    @Before
    public void setUp() {
        // Since GenericMetadataSupport is likely abstract or has internal dependencies, 
        // we spy on it to mock the abstract/protected methods.
        genericMetadataSupport = Mockito.spy(Mockito.mock(GenericMetadataSupport.class));
        mockRawType = Mockito.mock(Class.class);
    }

    @Test
    public void testActualTypeArguments_EmptyParameters() {
        // Arrange
        TypeVariable[] emptyParams = new TypeVariable[0];
        when(genericMetadataSupport.rawType()).thenReturn(mockRawType);
        when(mockRawType.getTypeParameters()).thenReturn(emptyParams);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testActualTypeArguments_WithMultipleParameters() {
        // Arrange
        TypeVariable tv1 = Mockito.mock(TypeVariable.class);
        TypeVariable tv2 = Mockito.mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{tv1, tv2};

        Type actualType1 = String.class;
        Type actualType2 = Integer.class;

        when(genericMetadataSupport.rawType()).thenReturn(mockRawType);
        when(mockRawType.getTypeParameters()).thenReturn(typeParameters);

        // Mocking the protected method getActualTypeArgumentFor
        when(genericMetadataSupport.getActualTypeArgumentFor(tv1)).thenReturn(actualType1);
        when(genericMetadataSupport.getActualTypeArgumentFor(tv2)).thenReturn(actualType2);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertEquals(2, result.size());
        assertEquals(actualType1, result.get(tv1));
        assertEquals(actualType2, result.get(tv2));

        // Verify order (LinkedHashMap)
        Type[] values = result.values().toArray();
        assertEquals(actualType1, values[0]);
        assertEquals(actualType2, values[1]);
    }

    @Test
    public void testActualTypeArguments_WithNullTypeArgument() {
        // Arrange
        TypeVariable tv1 = Mockito.mock(TypeVariable.class);
        TypeVariable[] typeParameters = new TypeVariable[]{tv1};

        when(genericMetadataSupport.rawType()).thenReturn(mockRawType);
        when(mockRawType.getTypeParameters()).thenReturn(typeParameters);
        // Simulate a case where the argument is null
        when(genericMetadataSupport.getActualTypeArgumentFor(tv1)).thenReturn(null);

        // Act
        Map<TypeVariable, Type> result = genericMetadataSupport.actualTypeArguments();

        // Assert
        assertEquals(1, result.size());
        assertTrue(result.containsKey(tv1));
        assertEquals(null, result.get(tv1));
    }
}
